member.example:
 namespace Example
 {
     interface IChildInterface {}

     interface IParentInterface : IBaseInterface {}

     interface IGrandParentInterface : IBaseInterface {}
}

 var publishedPluginInfo = new PublishedPluginInfo
 {
     ...
     ExposedTypes = new List<string>
                     {
                          typeof(IGrandParentInterface).FullName
                     },
     ...
 };

 var dict = publishedPluginInfo.GetExposedInterfaceTypes(out _);

 The dict will contain a key  IGrandParent with all types it implements including children interfaces that is

  {  "Example.IGrandParentInterface" : [ typeof(IGrandParentInterface), typeof(IParentInterface), typeof(IChildInterface) ] }
